view customer_orders.sql:
-- View: public.customer_orders

-- DROP VIEW public.customer_orders;

CREATE OR REPLACE VIEW public.customer_orders
 AS
 SELECT c.name,
    count(o.id) AS n
   FROM customers c
     LEFT JOIN orders o ON o.customer_id = c.id
  GROUP BY c.name;

ALTER TABLE public.customer_orders
    OWNER TO postgres;
COMMENT ON VIEW public.customer_orders
    IS 'orders per customer';

